<div class="page-heading"><div><p class="eyebrow">GRAVE PROFILE · #<?= (int) $grave['id'] ?></p><h1><?= e($grave['deceased_name']) ?></h1><p class="page-lead">A private record of the resting place and the details needed to find it.</p></div><div class="grave-heading-actions"><a class="btn btn-outline btn-primary btn-sm" href="?page=graves">All graves</a><a class="btn btn-primary btn-sm" href="?page=grave-form&amp;id=<?= (int) $grave['id'] ?>">Edit details <?= icon('arrow', 'size-4') ?></a></div></div>
