<?php if (count($gravePhotos) < GRAVE_PHOTO_LIMIT): ?><form class="grave-photo-upload" method="post" action="?page=grave&amp;id=<?= (int) $grave['id'] ?>" enctype="multipart/form-data"><?= csrf_field() ?><input type="hidden" name="action" value="upload_grave_photo"><input type="hidden" name="grave_id" value="<?= (int) $grave['id'] ?>"><div class="form-field"><label for="grave-photo-file">Add a photo</label><input class="file-input file-input-bordered w-full" id="grave-photo-file" name="photo" type="file" accept="image/jpeg,image/png,image/webp" required><small>JPEG, PNG, or WebP · up to 5 MB · up to 16 megapixels</small></div><div class="form-field"><label for="grave-photo-caption">Caption <span class="optional-label">Optional</span></label><input class="input input-bordered w-full" id="grave-photo-caption" name="caption" maxlength="200" placeholder="e.g. Headstone from the main path"></div><button class="btn btn-primary btn-sm" type="submit">Upload photo <?= icon('arrow', 'size-4') ?></button></form><?php endif; ?></section></div>
